def fence_remaining_commands_and_json(text: str) -> str:
    lines = text.splitlines()
    output: list[str] = []
    index = 0
    inside_fence = False
    restored_commands = 0
    restored_json = 0

    def unescape(value: str) -> str:
        value = value.strip()
        return re.sub(r"\\([_=\-\[\]{}*<>])", r"\1", value)

    def is_command(value: str) -> bool:
        return bool(
            re.match(r"^\s*(?:uv |git |cd |mkdir |python |pytest |ruff |ty |curl )", value)
        )

    while index < len(lines):
        line = lines[index]
        if line.startswith("```"):
            inside_fence = not inside_fence
            output.append(line)
            index += 1
            continue
        if inside_fence:
            output.append(line)
            index += 1
            continue

        if is_command(line):
            commands: list[str] = []
            cursor = index
            while cursor < len(lines):
                candidate = lines[cursor]
                if is_command(candidate):
                    commands.append(unescape(candidate))
                    cursor += 1
                    continue
                if not candidate.strip() and cursor + 1 < len(lines) and is_command(lines[cursor + 1]):
                    cursor += 1
                    continue
                break
            output.extend(["```console", *commands, "```"])
            restored_commands += 1
            index = cursor
            continue

        stripped = line.strip()
        if len(stripped) >= 20 and stripped.startswith("{") and stripped.endswith("}"):
            output.extend(["```json", unescape(stripped), "```"])
            restored_json += 1
            index += 1
            continue

        output.append(line)
        index += 1

    if inside_fence:
        raise ValueError("Unclosed fenced block while restoring commands")
    if restored_commands < 15 or restored_json < 1:
        raise ValueError(
            f"Expected at least 15 command groups and one JSON output, found "
            f"{restored_commands} and {restored_json}"
        )
    return "\n".join(output).rstrip() + "\n"


def label_long_technical_blocks(text: str) -> str:
    lines = text.splitlines()
    insertions: dict[int, str] = {}
    inside = False
    start = 0
    language = ""
    block: list[str] = []

    for index, line in enumerate(lines):
        if not line.startswith("```"):
            if inside:
                block.append(line)
            continue
        if not inside:
            inside = True
            start = index
            language = line[3:].strip() or "text"
            block = []
            continue

        if len(block) > 20:
            nearby = [value.strip() for value in lines[max(0, start - 8) : start] if value.strip()]
            introduced = any(
                re.search(r"(?:Листинг|Пример|Конфигурация)", value, re.IGNORECASE)
                for value in nearby[-4:]
            )
            if not introduced:
                heading = next(
                    (
                        clean_inline_markup(value.lstrip("# ").strip())
                        for value in reversed(lines[:start])
                        if value.startswith("### ")
                    ),
                    "Технический контракт",
                )
                kind = {
                    "yaml": "декларативная конфигурация",
                    "json": "структурированный результат",
                    "python": "учебный пример Python",
                    "pseudocode": "псевдокод",
                }.get(language, "технический пример")
                insertions[start] = (
                    f"**Листинг. {heading}.** Тип: {kind}; полный учебный контракт "
                    "приведен ниже."
                )
        inside = False

    if inside:
        raise ValueError("Unclosed fenced block while labeling long examples")
    if len(insertions) != 8:
        raise ValueError(
            f"Expected eight previously unlabeled long examples, found {len(insertions)}"
        )

    output: list[str] = []
    for index, line in enumerate(lines):
        if index in insertions:
            if output and output[-1].strip():
                output.append("")
            output.extend((insertions[index], ""))
        output.append(line)
    return "\n".join(output).rstrip() + "\n"


def number_listings(text: str) -> str:
    counter = 0

    def replacement(match: re.Match[str]) -> str:
        nonlocal counter
        counter += 1
        return f"**Листинг {counter}."

    text = re.sub(r"\*\*Листинг(?: \d+)?\.", replacement, text)
    if counter < 30:
        raise ValueError(f"Expected at least 30 labeled listings, found {counter}")
    return text


def insert_listing_reading_guides(text: str) -> str:
    lines = text.splitlines()
    output: list[str] = []
    listing_number = 0
    index = 0

    while index < len(lines):
        line = lines[index]
        if not re.match(r"^\*\*Листинг \d+\.", line):
            output.append(line)
            index += 1
            continue

        listing_number += 1
        output.append(line)
        index += 1
        while index < len(lines) and lines[index].strip():
            output.append(lines[index])
            index += 1

        if listing_number > len(LISTING_READING_GUIDES):
            raise ValueError("Listing guide mapping does not cover every listing")
        output.extend(
            (
                "",
                f"**Как читать листинг.** {LISTING_READING_GUIDES[listing_number - 1]}",
            )
        )

    if listing_number != len(LISTING_READING_GUIDES):
        raise ValueError(
            f"Expected {len(LISTING_READING_GUIDES)} listings, found {listing_number}"
        )
    return "\n".join(output).rstrip() + "\n"


def upgrade_practical_path(text: str) -> str:
    lab3 = r'''### Лабораторная работа 3\. Память и межарендаторная граница

Цель: доказать наблюдаемым отрицательным результатом, что область арендатора
является частью контракта памяти, а не скрытым свойством хранилища.

**Команды.**

    uv run python -m agent_runtime_ref inspect-memory --tenant-id tenant-acme --memory-class profile
    uv run python -m agent_runtime_ref inspect-memory --tenant-id tenant-beta --memory-class profile
    uv run python -m agent_runtime_ref simulate-run --trace-id trace-lab-03 --session-id session-lab-03 --user-input "What language preference do you remember?"

**Ожидаемый результат.** Первый запрос возвращает одну запись `mem-001` с
`provenance=user_confirmed_preference` и `revision=1`. Второй запрос возвращает
`count=0`, пустые `memory_ids` и `records`: данные `tenant-acme` не становятся
видимыми для `tenant-beta`. Запуск с `trace-lab-03` использует только состояние
своего арендатора.

**Артефакт.** Короткий протокол `lab-03-memory-boundary.md`: две команды,
наблюдаемые количества записей, правило хранения для каждого класса памяти и
описание того, что проверка доказывает и чего не доказывает.

Критерий приемки: положительный и отрицательный результаты воспроизводимы;
граница арендатора видна в команде и ответе. Отдельно зафиксировано, что учебная
среда хранит данные в памяти процесса и не реализует долговечное удаление,
карантин или откат записи.'''
    text = replace_between(
        text,
        "### Лабораторная работа 3\\. Память и межарендаторная граница",
        "# Часть IV. Инструменты, выполнение и интеграция",
        lab3,
    )

    lab5 = r'''### Лабораторная работа 5\. От трассы к оценке и решению о выпуске

Цель: собрать один проверяемый пакет отказа и честно разделить связь по
идентификаторам внутри артефакта и связь по сценарию между разными экспортами.

**Команды.**

    mkdir -p artifacts/lab-05
    uv run python -m agent_runtime_ref export-events --trace-id trace-lab-05-01 --session-id session-lab-05 --simulate-failure tool_timeout --output artifacts/lab-05/trace.jsonl
    uv run python -m agent_runtime_ref inspect-trace --input artifacts/lab-05/trace.jsonl
    uv run python -m agent_runtime_ref export-session --session-id session-lab-05 --trace-prefix trace-lab-05 --simulate-failure tool_timeout --output artifacts/lab-05/session.json
    uv run python -m agent_runtime_ref export-eval-dataset --scenario failed_run_timeout --session-prefix session-lab-05 --output artifacts/lab-05/eval.json
    uv run python -m agent_runtime_ref check-rollout --signal duplicate_ticket_eval_passed=false

**Ожидаемый результат.** Трасса `trace-lab-05-01` относится к
`session-lab-05`, завершается со `status=failed`, содержит
`failure_reason=tool_timeout`, десять событий и ключ идемпотентности. Экспорт
сессии сохраняет собственные связанные идентификаторы запусков. Набор оценки
содержит сценарий `failed_run_timeout`, а выпускной шлюз возвращает
`ready=false` и `missing_required=["duplicate_ticket_eval_passed"]`.

Экспорты сессии и набора оценки генерируют собственные идентификаторы. Поэтому
связь между ними в этой лабораторной работе основана на типе сценария,
`failure_reason` и явном манифесте упражнения, а не на вымышленном совпадении
`trace_id`. Запишите эти ссылки в `artifacts/lab-05/evidence.yaml`.

Критерий приемки: внутри каждого артефакта идентификаторы согласованы; между
артефактами явно записано основание связи; читатель отличает измеренный отказ
от декларативного сигнала выпускного шлюза и не выдает учебный булев сигнал за
промышленную аттестацию.'''
    text = replace_between(
        text,
        "### Лабораторная работа 5\\. От трассы к оценке и решению о выпуске",
        "# Часть VI. Организационная модель и жизненный цикл",
        lab5,
    )

    capstone = r'''## Итоговый проект. Аудит готовности агента поддержки

Итоговый проект не требует объявить учебный стенд промышленно готовым. Его
задача — пройти полный путь доказательств и принять обоснованное решение о
первой волне. Работайте в каталоге `artifacts/capstone` и сохраняйте вывод
каждой команды.

### Этап 1. Зафиксировать контракт и исходное состояние

Выберите `create_ticket` как записывающую возможность. Сохраните запись
возможности, решение политики, владельца, риск, требование подтверждения и ключ
идемпотентности. Выполните `inspect-agent`, `inspect-approvals` и
`inspect-lifecycle`.

Результат этапа: `01-baseline.md` с границами системы и списком свойств, которые
эталонный пакет не доказывает.

### Этап 2. Получить обычный и неуспешный пути

Экспортируйте обычную трассу и трассу с `tool_timeout`. Для обеих задайте
явные `session_id` и `trace_id`, затем проверьте их через `inspect-trace`.

Результат этапа: две трассы и таблица различий по решению политики, внешнему
эффекту, причине завершения и допустимости повтора.

### Этап 3. Проверить неизвестный или неполный эффект

Объясните, почему тайм-аут транспорта не доказывает отсутствие заявки во
внешней системе. Добавьте в проект контракт сверки: бизнес-ключ, запрос
фактического состояния, возможные ответы, владелец неоднозначного результата и
запрет автоматического повтора до `verification_result`.

Результат этапа: `03-reconciliation.yaml` и короткий разбор инцидента по шаблону
приложения 3.

### Этап 4. Связать измерение, оценку и выпуск

Рассчитайте SLI для известного статуса высокорисковых эффектов, добавьте
неуспешный сценарий в оценочный пакет и выполните отрицательный
`check-rollout`. Создайте `evidence-manifest.yaml`, который связывает контракт,
трассы, расчет SLO, оценочный сценарий и решение шлюза.

Результат этапа: решение `hold` с перечислением отсутствующих доказательств, а
не общий вывод «система небезопасна».

### Этап 5. Спроектировать путь к ограниченной волне

Не меняя фактический результат стенда, опишите, какие проверяемые свойства
позволили бы перейти от `hold` к `limited_wave`: долговечное подтверждение,
сверка внешнего эффекта, подтвержденная оценка дублей, ограничение арендаторов,
дежурный владелец, безопасный режим и испытанный откат. Для каждого свойства
укажите источник сигнала и способ отрицательной проверки.

Результат этапа: `05-limited-wave-plan.md` с максимальным охватом, условиями
остановки и ответственным за решение.

### Рубрика проекта

Проект оценивается по двадцати баллам: по четыре балла за воспроизводимость
команд, связность идентификаторов, качество отрицательных проверок, честность
границы доказательств и обоснованность решения о выпуске. Проект принят при
результате не ниже 16 баллов и нуле по любому из двух критериев-блокеров:
неизвестный внешний эффект или отсутствие владельца остановки.

Финальное решение для текущего эталонного пакета остается `hold`. Сильный
результат проекта состоит не в обходе этого ограничения, а в точном объяснении,
какие доказательства отсутствуют и как команда должна их получить.'''
    text = replace_between(
        text,
        "## Итоговый проект. От запроса поддержки до обоснованной остановки выпуска",
        "Рисунок 25\\. Итоговый пакет доказательств",
        capstone,
    )

    chapter14_start = text.index("## Глава 14\\. SLO для агентных систем")
    chapter15_start = text.index("## Глава 15\\. Офлайн- и онлайн-оценки")
    chapter14 = text[chapter14_start:chapter15_start]
    anchor = "**Практическая проверка**"
    if anchor not in chapter14:
        raise ValueError("Chapter 14 practical-check anchor is missing")
    slo_example = r'''### Расчетный пример: SLO известного внешнего эффекта

Возьмем 28-дневное окно и высокорисковые действия создания заявки. Знаменатель
SLI — все 10 000 действий, дошедших до точки намерения записи. Тестовый трафик
и запросы, отмененные до этой точки, исключаются. Числитель — 9 870 действий,
для которых в течение пяти минут получен однозначный статус внешнего эффекта.
Источником служит связка событий `tool_execution`, `verification_result` и
`run_complete` по одному ключу идемпотентности.

    SLI = 9 870 / 10 000 = 98,7 %
    SLO = 99,0 %
    допустимое число неизвестных исходов = 10 000 × (1 - 0,99) = 100
    фактическое число неизвестных исходов = 130
    расход бюджета ошибок = 130 / 100 = 130 %
    скорость расходования бюджета = 1,3

Бюджет исчерпан на 130 процентов, поэтому расширять волну нельзя. Команда
останавливает рост охвата, разбирает 130 неизвестных исходов и возвращается к
решению только после восстановления `verification_result`. Такой расчет
отличает SLO от порога в YAML: в нем заданы окно, знаменатель, исключения,
источник данных и управленческое действие.

Практическое задание: повторите расчет для окна в семь дней и отдельно
посчитайте скорость расходования за последний час. Если часовой показатель
существенно выше долгосрочного, сформулируйте условие немедленной остановки.'''
    chapter14 = chapter14.replace(anchor, slo_example + "\n\n" + anchor, 1)
    return text[:chapter14_start] + chapter14 + text[chapter15_start:]


def enrich_laboratory_contracts(text: str) -> str:
    pattern = re.compile(
        r"(?ms)^(### Лабораторная работа (\d+)\\\..*?)"
        r"(?=^# Часть |^## Итоговый проект|^# Заключение|\Z)"
    )
    seen: set[int] = set()

    def replacement(match: re.Match[str]) -> str:
        number = int(match.group(2))
        if number not in LAB_CONTRACTS:
            raise ValueError(f"Laboratory contract is missing: {number}")
        seen.add(number)
        prereq, timing, negative, troubleshooting, stretch = LAB_CONTRACTS[number]
        prereq = prereq[:1].upper() + prereq[1:]
        negative = negative[:1].upper() + negative[1:]
        troubleshooting = troubleshooting[:1].upper() + troubleshooting[1:]
        stretch = stretch[:1].upper() + stretch[1:]
        lab = match.group(1).rstrip()
        heading, body = lab.split("\n", 1)
        opening = (
            f"{heading}\n\n**Предварительные условия.** {prereq}.\n\n"
            f"**Ориентировочное время.** {timing}."
        )
        closing = (
            f"**Отрицательная проверка.** {negative}.\n\n"
            f"**Если результат отличается.** {troubleshooting}.\n\n"
            f"**Дополнительное задание.** {stretch}."
        )
        return f"{opening}\n\n{body.strip()}\n\n{closing}\n\n"

    text = pattern.sub(replacement, text)
    missing = set(LAB_CONTRACTS) - seen
    if missing:
        raise ValueError(f"Laboratory contracts were not inserted: {sorted(missing)}")
    return text.rstrip() + "\n"


