    for old, new in repeated_conclusions.items():
        if text.count(old) != 1:
            raise ValueError(f"Repeated conclusion anchor changed: {old[:72]}")
        text = text.replace(old, new, 1)

    modality_anchor = (
        "**Граница переносимости источников.** Нормативный документ задает рамку, "
        "исследование показывает наблюдаемый результат и ограничения метода, а "
        "платформенная документация описывает конкретную реализацию на дату "
        "проверки; платформенный пример не следует читать как универсальную гарантию."
    )
